const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN'}).format(n),number=(n,d=3)=>new Intl.NumberFormat('pl-PL',{maximumFractionDigits:d}).format(n);
const DEFAULT_BASE=3,OUNCE=31.1034768;
function baseRate(){const value=Number(localStorage.getItem('silverStudioBaseRate'));return Number.isFinite(value)&&value>0&&value<=10000?value:DEFAULT_BASE;}
const presets={coins:[['ounce','Moneta 1 oz · próba 999',OUNCE,999],['half','Moneta 1/2 oz · próba 999',OUNCE/2,999],['custom','Własna moneta — podaj parametry',null,null]],bars:[['100','Sztabka 100 g · próba 999',100,999],['ounce','Sztabka 1 oz · próba 999',OUNCE,999],['250','Sztabka 250 g · próba 999',250,999],['500','Sztabka 500 g · próba 999',500,999],['1000','Sztabka 1 kg · próba 999',1000,999],['custom','Własna sztabka — podaj parametry',null,null]],scrap:[['jewelry','Biżuteria / złom srebrny',null,null],['cutlery','Sztućce / srebro użytkowe',null,null]]};
const labels={coins:'Monety',bars:'Sztabki',scrap:'Biżuteria i złom'};
let kind='scrap',items=[],current=null,nextId=1;
function configureCategory(value){if(!presets[value])throw Error('Nieznany rodzaj srebra');kind=value;document.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.kind===kind));$('preset').replaceChildren(...presets[kind].map(p=>new Option(p[1],p[0])));$('quantity-label').hidden=kind==='scrap';$('deduction-label').hidden=kind!=='scrap';$('weight-label').textContent=kind==='scrap'?'Waga całego przedmiotu (g)':'Waga jednej sztuki (g)';$('calc-help').textContent=kind==='scrap'?'Odejmij masę kamieni i elementów wykonanych z innych materiałów.':'Wycena dotyczy zawartości metalu. Wartość kolekcjonerska nie jest uwzględniona.';$('quantity').value='1';$('deduction').value='0';if(kind==='scrap'){$('weight').value=100;$('purity').value=925;}applyPreset();}
function applyPreset(){const p=presets[kind].find(p=>p[0]===$('preset').value);if(p?.[2]!=null){$('weight').value=p[2];$('purity').value=p[3];}updateCalc();}
function calculate(k,w,p,q,d){if(!presets[k])throw Error('Wybierz rodzaj srebra.');if(!Number.isFinite(w)||w<=0||w>1000000)throw Error('Podaj wagę większą od 0 i nie większą niż 1 000 000 g.');if(![800,830,835,875,900,925,999].includes(p))throw Error('Wybierz prawidłową próbę.');if(!Number.isInteger(q)||q<1||q>10000)throw Error('Liczba sztuk musi być całkowita, od 1 do 10 000.');if(!Number.isFinite(d)||d<0||d>=w)throw Error('Masa pozostałych części musi być mniejsza niż waga przedmiotu.');const net=(w-d)*q,fine=net*p/1000;return {kind:k,weight:w,purity:p,quantity:q,deduction:d,net,fine,value:fine*baseRate(),rate:p/1000*baseRate()};}
function updateCalc(){try{if($('weight').value===''||(kind!=='scrap'&&$('quantity').value==='')||(kind==='scrap'&&$('deduction').value===''))throw Error('Uzupełnij wszystkie pola liczbowe.');current=calculate(kind,+$('weight').value,+$('purity').value,kind==='scrap'?1:+$('quantity').value,kind==='scrap'?+$('deduction').value:0);$('calc-error').hidden=true;$('result').textContent=money(current.value);$('net-weight').textContent=number(current.net)+' g';$('fine-weight').textContent=number(current.fine)+' g';$('gram-rate').textContent=number(current.rate)+' zł';$('add-item').disabled=false;}catch(e){current=null;$('calc-error').hidden=false;$('calc-error').textContent=e.message;$('result').textContent='—';['net-weight','fine-weight','gram-rate'].forEach(id=>$(id).textContent='—');$('add-item').disabled=true;}}
document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>configureCategory(b.dataset.kind));document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{configureCategory(b.dataset.category);$('kalkulator').scrollIntoView({behavior:'smooth'});});$('preset').onchange=applyPreset;['weight','purity','quantity','deduction'].forEach(id=>$(id).addEventListener('input',()=>{if(['weight','purity'].includes(id)&&kind!=='scrap')$('preset').value='custom';updateCalc();}));
$('calc-form').onsubmit=e=>{e.preventDefault();updateCalc();if(current){items.push({...current,id:nextId++});renderBasket();}};
function renderBasket(){$('basket-list').replaceChildren();for(const item of items){const li=document.createElement('li'),desc=document.createElement('div'),title=document.createElement('b'),detail=document.createElement('span'),value=document.createElement('strong'),remove=document.createElement('button');title.textContent=labels[item.kind]+' · próba '+item.purity;detail.textContent=`${item.quantity>1?item.quantity+' szt. × ':''}${number(item.weight)} g${item.deduction?' − '+number(item.deduction)+' g innych części':''}`;desc.append(title,detail);value.textContent=money(item.value);remove.textContent='Usuń';remove.className='text-button';remove.setAttribute('aria-label','Usuń '+labels[item.kind]+' z wyceny');remove.onclick=()=>{items=items.filter(i=>i.id!==item.id);renderBasket();};li.append(desc,value,remove);$('basket-list').append(li);}$('empty-basket').hidden=!!items.length;$('item-count').textContent=items.length;$('basket-total').textContent=money(items.reduce((s,i)=>s+i.value,0));['copy-quote','ask-quote','clear-items'].forEach(id=>$(id).disabled=!items.length);$('copy-status').textContent='';}
function quoteText(){return 'Wycena demonstracyjna srebra\n'+items.map((i,index)=>`${index+1}. ${labels[i.kind]}, próba ${i.purity}, masa netto ${number(i.net)} g: ${money(i.value)}`).join('\n')+'\nRazem: '+money(items.reduce((s,i)=>s+i.value,0))+'\nStawki przykładowe, do potwierdzenia w punkcie.';}
async function copyText(text,status){try{await navigator.clipboard.writeText(text);$(status).textContent='Skopiowano.';}catch{$(status).textContent='Kopiowanie niedostępne. Zaznacz i skopiuj tekst ręcznie.';if(status==='copy-status'){let box=$('quote-fallback');if(!box){box=document.createElement('textarea');box.id='quote-fallback';box.readOnly=true;box.setAttribute('aria-label','Podsumowanie do ręcznego skopiowania');$('basket-list').after(box);}box.value=text;box.focus();box.select();}}}
$('clear-items').onclick=()=>{items=[];renderBasket();};$('copy-quote').onclick=()=>copyText(quoteText(),'copy-status');$('ask-quote').onclick=()=>{$('contact-message').value='Dzień dobry, proszę o wycenę poniższych przedmiotów.\n\n'+quoteText();$('kontakt').scrollIntoView({behavior:'smooth'});};
[999,925,900,875,835,830,800].forEach(p=>{const tr=document.createElement('tr');tr.innerHTML=`<td><b>${p}</b></td><td>${number(p/10)}%</td><td>${number(p/1000*baseRate())} zł</td><td><button class="text-button" data-price="${p}">Wyceń</button></td>`;$('price-rows').append(tr);});document.querySelectorAll('[data-price]').forEach(b=>b.onclick=()=>{configureCategory('scrap');$('purity').value=b.dataset.price;updateCalc();$('kalkulator').scrollIntoView({behavior:'smooth'});});
configureCategory('scrap');renderBasket();

const allData=Array.from({length:90},(_,i)=>{const date=new Date(Date.UTC(2026,6,2+i));const raw=2.48+i*.006+Math.sin(i*.54)*.055+Math.cos(i*.17)*.07;return {date:date.toISOString().slice(0,10),value:Math.round(raw*1000)/1000};});allData[89].value=3;
let period=30,chartPoints=[];const formatDate=s=>new Date(s+'T12:00:00Z').toLocaleDateString('pl-PL',{day:'2-digit',month:'2-digit'});
function drawChart(){const data=allData.slice(-period),svg=$('chart'),width=Math.max(260,svg.parentElement.clientWidth),height=270,L=52,R=24,T=20,B=40;svg.setAttribute('viewBox',`0 0 ${width} ${height}`);const min=Math.floor((Math.min(...data.map(d=>d.value))-.04)*10)/10,max=Math.ceil((Math.max(...data.map(d=>d.value))+.04)*10)/10;const x=i=>L+i/(data.length-1)*(width-L-R),y=n=>T+(max-n)/(max-min)*(height-T-B);chartPoints=data.map((d,i)=>({...d,x:x(i),y:y(d.value)}));let markup='<title>Symulacja ceny srebra — '+period+' dni, zł za gram</title>';for(let i=0;i<5;i++){const value=min+(max-min)*i/4,yy=y(value);markup+=`<line x1="${L}" x2="${width-R}" y1="${yy}" y2="${yy}" class="gridline"/><text x="${L-10}" y="${yy+4}" text-anchor="end">${value.toFixed(2).replace('.',',')}</text>`;}const indices=[0,Math.round((data.length-1)/3),Math.round((data.length-1)*2/3),data.length-1];for(const i of indices)markup+=`<text x="${x(i)}" y="${height-12}" text-anchor="${i===0?'start':i===data.length-1?'end':'middle'}">${formatDate(data[i].date)}</text>`;const points=chartPoints.map(p=>`${p.x},${p.y}`).join(' ');markup+=`<polygon points="${L},${height-B} ${points} ${width-R},${height-B}" class="chart-fill"/><polyline points="${points}" class="chart-line"/><circle cx="${width-R}" cy="${y(data.at(-1).value)}" r="4" class="chart-point"/><text x="${L}" y="13" class="axis-label">zł / g</text><line id="chart-guide" x1="0" x2="0" y1="${T}" y2="${height-B}" hidden class="chart-guide"/>`;svg.innerHTML=markup;$('chart-range').textContent=`${formatDate(data[0].date)}–${formatDate(data.at(-1).date)}.2026`;$('chart-last').textContent=money(data.at(-1).value);$('chart-table').innerHTML=data.map(d=>`<tr><td>${d.date}</td><td>${number(d.value)} zł</td></tr>`).join('');$('chart-tooltip').hidden=true;}
document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=+b.dataset.period;document.querySelectorAll('[data-period]').forEach(t=>t.setAttribute('aria-pressed',t===b));drawChart();});
$('chart').addEventListener('pointermove',e=>{const bounds=$('chart').getBoundingClientRect(),pos=e.clientX-bounds.left;const point=chartPoints.reduce((a,b)=>Math.abs(a.x-pos)<Math.abs(b.x-pos)?a:b);const tip=$('chart-tooltip');tip.textContent=formatDate(point.date)+'.2026 · '+number(point.value)+' zł/g';tip.hidden=false;tip.style.left=Math.min(Math.max(0,point.x-65),bounds.width-185)+'px';tip.style.top='10px';const line=$('chart-guide');line.removeAttribute('hidden');line.setAttribute('x1',point.x);line.setAttribute('x2',point.x);});$('chart').addEventListener('pointerleave',()=>{$('chart-tooltip').hidden=true;$('chart-guide')?.setAttribute('hidden','');});new ResizeObserver(drawChart).observe($('chart').parentElement);drawChart();
$('contact-form').onsubmit=e=>{e.preventDefault();if(!$('contact-form').reportValidity())return;$('message-output').value=`Zapytanie o skup srebra\nOd: ${$('contact-name').value.trim()}\nKontakt: ${$('contact-email').value.trim()}\n\n${$('contact-message').value.trim()}`;$('message-preview').hidden=false;$('message-status').textContent='Treść gotowa. Wiadomość nie została wysłana.';};$('copy-message').onclick=()=>copyText($('message-output').value,'message-status');$('privacy-open').onclick=()=>$('privacy').showModal();$('privacy-close').onclick=()=>$('privacy').close();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'preview_silver_valuation',title:'Oblicz demonstracyjną wartość srebra',description:'Ustawia widoczny kalkulator i zwraca wycenę demonstracyjną. Nie dodaje pozycji ani nie wysyła wiadomości.',inputSchema:{type:'object',properties:{kind:{type:'string',enum:['coins','bars','scrap']},weight:{type:'number',exclusiveMinimum:0},purity:{type:'integer',enum:[800,830,835,875,900,925,999]},quantity:{type:'integer',minimum:1},deduction:{type:'number',minimum:0}},required:['kind','weight','purity'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const q=input.kind==='scrap'?1:(input.quantity??1),d=input.kind==='scrap'?(input.deduction??0):0;const result=calculate(input.kind,input.weight,input.purity,q,d);configureCategory(input.kind);$('weight').value=input.weight;$('purity').value=input.purity;$('quantity').value=q;$('deduction').value=d;if(input.kind!=='scrap')$('preset').value='custom';updateCalc();return {demonstration:true,valuePLN:Math.round(result.value*100)/100,netGrams:result.net,fineSilverGrams:result.fine};}})).catch(()=>{});}catch{}}
